#!/bin/bash
set -e

echo "=========================================="
echo "  HealthLens Creem Payment Deployment"
echo "=========================================="
echo ""

# Find the project directory
PROJECT_DIR="/root/healthlens"
if [ ! -d "$PROJECT_DIR" ]; then
    echo "[INFO] Searching for healthlens directory..."
    FOUND=$(find / -maxdepth 4 -name "docker-compose.yml" -path "*/healthlens/*" 2>/dev/null | head -1)
    if [ -n "$FOUND" ]; then
        PROJECT_DIR=$(dirname "$FOUND")
    else
        echo "[ERROR] Cannot find healthlens project directory"
        exit 1
    fi
fi
echo "[INFO] Project directory: $PROJECT_DIR"

# Step 1: Decode and extract files
echo ""
echo "[1/6] Extracting deployment files..."
cd "$PROJECT_DIR"
echo '' | base64 -d > /tmp/creem_deploy.zip
unzip -o /tmp/creem_deploy.zip -d /tmp/creem_deploy/
echo "  -> Files extracted to /tmp/creem_deploy/"

# Step 2: Deploy backend files
echo ""
echo "[2/6] Deploying backend files..."
for f in app/services/creem_pay_service.py app/api/payment.py app/api/tiered_growth.py; do
    if [ -f "/tmp/creem_deploy/$f" ]; then
        TARGET="$PROJECT_DIR/$f"
        mkdir -p "$(dirname "$TARGET")"
        cp "/tmp/creem_deploy/$f" "$TARGET"
        echo "  -> Deployed: $f"
    fi
done

# Step 3: Deploy frontend files
echo ""
echo "[3/6] Deploying frontend files..."
for f in frontend/assets/app.v2.js frontend/index.html; do
    if [ -f "/tmp/creem_deploy/$f" ]; then
        TARGET="$PROJECT_DIR/$f"
        mkdir -p "$(dirname "$TARGET")"
        cp "/tmp/creem_deploy/$f" "$TARGET"
        echo "  -> Deployed: $f"
    fi
done

# Step 4: Update .env with CREEM_API_KEY
echo ""
echo "[4/6] Updating .env with Creem API key..."
ENV_FILE="$PROJECT_DIR/.env"
if [ ! -f "$ENV_FILE" ]; then
    echo "[WARNING] .env file not found at $ENV_FILE"
    echo "[INFO] Creating .env file..."
    touch "$ENV_FILE"
fi

# Remove old CREEM_API_KEY if exists
sed -i '/^CREEM_API_KEY=/d' "$ENV_FILE"
# Add new CREEM_API_KEY
echo "CREEM_API_KEY=creem_4yM8aDDK17QiHjWdiWgQEA" >> "$ENV_FILE"
echo "  -> CREEM_API_KEY added to .env"

# Step 5: Copy frontend files into Docker container
echo ""
echo "[5/6] Copying frontend files into Docker container..."
CONTAINER=$(docker ps --format "{{.Names}}" | grep -i health | head -1)
if [ -n "$CONTAINER" ]; then
    echo "  -> Container: $CONTAINER"
    docker cp "$PROJECT_DIR/frontend/assets/app.v2.js" "$CONTAINER:/app/frontend/assets/app.v2.js"
    echo "  -> Copied: app.v2.js"
    docker cp "$PROJECT_DIR/frontend/index.html" "$CONTAINER:/app/frontend/index.html"
    echo "  -> Copied: index.html"
    
    # Restart container to pick up new env vars
    echo "  -> Restarting container..."
    docker restart "$CONTAINER"
    echo "  -> Container restarted"
else
    echo "  [WARNING] No HealthLens container found"
    echo "  [INFO] If using docker-compose, run: docker compose restart web"
fi

# Step 6: Verify deployment
echo ""
echo "[6/6] Verifying deployment..."
sleep 5

# Check packages API
PKG_RESP=$(curl -s "https://healthlens.cc/api/v1/growth/points/packages" 2>/dev/null || curl -s "http://localhost:8000/api/v1/growth/points/packages" 2>/dev/null || echo "")
PKG_COUNT=$(echo "$PKG_RESP" | python3 -c "import sys,json; d=json.load(sys.stdin); print(len(d.get('data',[])))" 2>/dev/null || echo "0")
echo "  -> Packages available: $PKG_COUNT"

# Check Creem webhook endpoint
WEBHOOK_RESP=$(curl -s -o /dev/null -w "%{http_code}" -X POST "https://healthlens.cc/api/v1/payment/creem/webhook" -H "Content-Type: application/json" -d '{"test":true}' 2>/dev/null || echo "000")
echo "  -> Creem webhook endpoint: HTTP $WEBHOOK_RESP"

# Check frontend
JS_SIZE=$(curl -s "https://healthlens.cc/assets/app.v2.js" 2>/dev/null | wc -c)
echo "  -> Frontend app.v2.js size: $JS_SIZE bytes"

HAS_CREEM=$(curl -s "https://healthlens.cc/assets/app.v2.js" 2>/dev/null | grep -c "creem" || echo "0")
echo "  -> Frontend has Creem code: $HAS_CREEM matches"

echo ""
echo "=========================================="
if [ "$PKG_COUNT" -gt 0 ] && [ "$WEBHOOK_RESP" != "404" ]; then
    echo "  DEPLOYMENT SUCCESSFUL!"
    echo "  - Packages: $PKG_COUNT"
    echo "  - Creem webhook: HTTP $WEBHOOK_RESP"
    echo "  - Frontend Creem: $HAS_CREEM matches"
    echo ""
    echo "  You can now test the payment flow at:"
    echo "  https://healthlens.cc"
else
    echo "  DEPLOYMENT INCOMPLETE"
    echo "  - Packages: $PKG_COUNT"
    echo "  - Creem webhook: HTTP $WEBHOOK_RESP"
    echo "  - Frontend Creem: $HAS_CREEM matches"
    echo ""
    echo "  Check container logs: docker logs $CONTAINER --tail 50"
fi
echo "=========================================="

# Cleanup
rm -f /tmp/creem_deploy.zip
rm -rf /tmp/creem_deploy/
